extension on _StringsEs {
	dynamic _flatMapFunction(String path) {
		switch (path) {
			case 'app_title': return 'PokéBóveda';
			case 'no_dex': return 'Aún no hay Dex.\n¡Haz clic en \'+\' para crear uno!';
			case 'import_tooltip': return 'Importar';
			case 'export_tooltip': return 'Exportar';
			case 'create_dex_title': return 'Crear nuevo Dex';
			case 'create_dex_hint': return 'Nombre (por ejemplo, Mi carrera)';
			case 'cancel': return 'Cancelar';
			case 'back': return 'Volver';
			case 'create': return 'Crear';
			case 'region': return 'Región';
			case 'caught': return 'atrapado';
			case 'search_hint': return 'Buscar (nombre o DNI)...';
			case 'filter_all': return 'Todos';
